def kmeans_centers(points, n_clusters):
    if not points or n_clusters <= 0 or n_clusters > len(points):
        raise ValueError("Invalid inputs")
    pts = [(float(p[0]), float(p[1])) for p in points]

    def d2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    best = None
    for start in range(len(pts)):
        centers = [pts[start]]
        while len(centers) < n_clusters:
            centers.append(max(pts, key=lambda p: min(d2(p, c) for c in centers)))
        for _ in range(300):
            groups = [[] for _ in centers]
            for p in pts:
                i = min(range(len(centers)), key=lambda j: d2(p, centers[j]))
                groups[i].append(p)
            new = [
                (sum(x for x, _ in g) / len(g), sum(y for _, y in g) / len(g)) if g else centers[i]
                for i, g in enumerate(groups)
            ]
            if new == centers:
                break
            centers = new
        inertia = sum(min(d2(p, c) for c in centers) for p in pts)
        if best is None or inertia < best[0]:
            best = (inertia, centers)
    return sorted([list(c) for c in best[1]])

