def fit_linear_regression(features, values):
    n = len(values)
    p = len(features[0])
    xm = [sum(r[j] for r in features) / n for j in range(p)]
    ym = sum(values) / n
    xc = [[r[j] - xm[j] for j in range(p)] for r in features]
    yc = [v - ym for v in values]
    a = []
    for i in range(p):
        row = [sum(x[i] * x[j] for x in xc) for j in range(p)]
        row.append(sum(x[i] * y for x, y in zip(xc, yc)))
        a.append(row)
    for col in range(p):
        piv = max(range(col, p), key=lambda r: abs(a[r][col]))
        a[col], a[piv] = a[piv], a[col]
        for r in range(p):
            if r != col:
                f = a[r][col] / a[col][col]
                for c in range(col, p + 1):
                    a[r][c] -= f * a[col][c]
    coef = [a[i][p] / a[i][i] for i in range(p)]
    intercept = ym - sum(c * m for c, m in zip(coef, xm))
    return {'coefficients': coef, 'intercept': float(intercept)}

