from collections import Counter


def letter_count_correlations(strings):
    if not strings:
        return None
    counts = [Counter(s) for s in strings]
    letters = sorted(set().union(*counts))
    cols = {ch: [c[ch] for c in counts] for ch in letters}
    n = len(strings)
    means = {ch: sum(v) / n for ch, v in cols.items()}
    devs = {ch: [x - means[ch] for x in cols[ch]] for ch in letters}
    norms = {ch: math.sqrt(sum(d * d for d in devs[ch])) for ch in letters}
    result = {}
    for x in letters:
        row = {}
        for y in letters:
            cov = sum(a * b for a, b in zip(devs[x], devs[y]))
            row[y] = cov / (norms[x] * norms[y])
        result[x] = row
    return result

