import pandas as pd

def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    df = pd.read_csv(io.StringIO(csv_text), dtype=str, keep_default_na=False)
    if column_name not in df.columns:
        raise ValueError(f'Column {column_name} does not exist')
    try:
        start = datetime.strptime(start_date, '%Y-%m-%d')
        end = datetime.strptime(end_date, '%Y-%m-%d')
        dates = pd.to_datetime(df[column_name], format='%Y-%m-%d')
    except ValueError as e:
        raise ValueError('Dates must be YYYY-MM-DD') from e
    filtered = df[(dates >= start) & (dates <= end)]
    return [[str(v) for v in row] for row in filtered.values.tolist()]

