from statistics import fmean, pstdev

def standardize_columns(data):
    result = {}
    for name, values in data.items():
        present = [v for v in values if v is not None]
        mean = fmean(present)
        filled = [mean if v is None else float(v) for v in values]
        sd = pstdev(filled)
        result[name] = [(v - mean) / sd for v in filled]
    return result

def roc_points_and_auc(labels, scores):
    pos = sum(1 for y in labels if y == 1)
    neg = len(labels) - pos
    if pos == 0 or neg == 0:
        raise ValueError("labels must contain both classes")
    pairs = sorted(zip(scores, labels), key=lambda p: -p[0])
    points = [(0.0, 0.0)]
    tp = fp = 0
    i = 0
    n = len(pairs)
    while i < n:
        s = pairs[i][0]
        while i < n and pairs[i][0] == s:
            if pairs[i][1] == 1:
                tp += 1
            else:
                fp += 1
            i += 1
        points.append((fp / neg, tp / pos))
    area = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        area += (x2 - x1) * (y1 + y2) / 2
    return points, area

