import statistics

def summarize_histogram(values, bins):
    mean = statistics.fmean(values)
    std = statistics.pstdev(values)
    lo, hi = min(values), max(values)
    counts = [0] * bins
    width = hi - lo
    for x in values:
        idx = int((x - lo) * bins / width) if width else 0
        if idx >= bins:
            idx = bins - 1
        if idx < 0:
            idx = 0
        counts[idx] += 1
    return (mean, std, counts)

from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.state = 0  # 0 searching, 1 inside, 2 done
        self.depth = 0
        self.rows = []
        self.row = None
        self.cell = None

    def _close_cell(self):
        if self.cell is not None:
            if self.row is not None:
                self.row.append(''.join(self.cell))
            self.cell = None

    def handle_starttag(self, tag, attrs):
        if self.state == 0:
            if tag == 'table' and dict(attrs).get('class') == 'data-table':
                self.state = 1
                self.depth = 1
            return
        if self.state != 1:
            return
        if tag == 'table':
            self.depth += 1
        elif tag == 'tr':
            self._close_cell()
            self.row = []
            self.rows.append(self.row)
        elif tag == 'td':
            self._close_cell()
            self.cell = []

    def handle_endtag(self, tag):
        if self.state != 1:
            return
        if tag == 'table':
            self.depth -= 1
            if self.depth == 0:
                self._close_cell()
                self.row = None
                self.state = 2
        elif tag == 'td':
            self._close_cell()
        elif tag == 'tr':
            self._close_cell()
            self.row = None

    def handle_data(self, data):
        if self.state == 1 and self.cell is not None:
            self.cell.append(data)


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    return parser.rows

