from html.parser import HTMLParser

VOID = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'source', 'track', 'wbr'}


class _Node:
    def __init__(self, tag, attrs):
        self.tag = tag
        self.classes = (dict(attrs).get('class') or '').split()
        self.children = []


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None, [])
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, attrs)
        self.stack[-1].children.append(node)
        if tag not in VOID:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.stack[-1].children.append(_Node(tag, attrs))

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _descendants(node):
    for child in node.children:
        if isinstance(child, _Node):
            yield child
            yield from _descendants(child)


def _text(node):
    return ''.join(c if isinstance(c, str) else _text(c) for c in node.children)


def _first(node, tag, cls=None):
    for d in _descendants(node):
        if d.tag == tag and (cls is None or cls in d.classes):
            return d
    return None


def extract_article_info(html):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()
    result = []
    for div in _descendants(builder.root):
        if div.tag != 'div' or 'container' not in div.classes:
            continue
        h1 = _first(div, 'h1')
        date = _first(div, 'span', 'date')
        author = _first(div, 'span', 'author')
        result.append((
            _text(h1).strip() if h1 else 'No Title',
            _text(date).strip() if date else 'No Date',
            _text(author).strip() if author else 'No Author',
        ))
    return result

def precision_recall_points(labels, scores):
    total_pos = sum(1 for l in labels if l == 1)
    result = []
    for t in sorted(set(scores)):
        tp = fp = 0
        for l, s in zip(labels, scores):
            if s >= t:
                if l == 1:
                    tp += 1
                else:
                    fp += 1
        result.append((float(t), tp / (tp + fp), tp / total_pos))
    return result

def product_profit_report(records):
    totals = {}
    for product, sales, margin in records:
        s, p = totals.get(product, (0, 0.0))
        totals[product] = (s + sales, p + sales * margin)
    report = [(product, s, p) for product, (s, p) in totals.items()]
    report.sort(key=lambda row: row[2], reverse=True)
    return report

