def seasonal_decomposition(values, period, model):
    n = len(values)
    if n < 2 * period:
        raise ValueError('series must contain at least two complete periods')
    multiplicative = model.lower().startswith('m')
    if multiplicative and any(v <= 0 for v in values):
        raise ValueError('multiplicative model requires positive values')
    if period % 2 == 0:
        weights = [0.5] + [1.0] * (period - 1) + [0.5]
    else:
        weights = [1.0] * period
    weights = [w / period for w in weights]
    half = len(weights) // 2
    trend = [None] * n
    for i in range(half, n - half):
        trend[i] = sum(w * values[i - half + k] for k, w in enumerate(weights))
    detrended = []
    for v, t in zip(values, trend):
        if t is None:
            detrended.append(None)
        else:
            detrended.append(v / t if multiplicative else v - t)
    averages = []
    for p in range(period):
        vals = [d for d in detrended[p::period] if d is not None]
        averages.append(sum(vals) / len(vals))
    mean_avg = sum(averages) / period
    if multiplicative:
        averages = [a / mean_avg for a in averages]
    else:
        averages = [a - mean_avg for a in averages]
    seasonal = [averages[i % period] for i in range(n)]
    residual = []
    for d, s in zip(detrended, seasonal):
        if d is None:
            residual.append(None)
        else:
            residual.append(d / s if multiplicative else d - s)
    return {'trend': trend, 'seasonal': seasonal, 'residual': residual}

