def xml_to_dict(s):
    if not s or not s.strip():
        raise ValueError('empty XML input')
    root = ET.fromstring(s)

    def convert(el):
        d = {}
        for k, v in el.attrib.items():
            d['@' + k] = v
        for child in el:
            val = convert(child)
            if child.tag in d:
                if isinstance(d[child.tag], list):
                    d[child.tag].append(val)
                else:
                    d[child.tag] = [d[child.tag], val]
            else:
                d[child.tag] = val
        text = (el.text or '').strip()
        if text:
            if d:
                d['#text'] = text
            else:
                return text
        return d or None

    return {root.tag: convert(root)}

