def _reflect(p, n):
    if n == 1:
        return 0
    while p < 0 or p >= n:
        if p < 0:
            p = -p
        else:
            p = 2 * (n - 1) - p
    return p


def box_blur(image, kernel_size):
    if (not isinstance(kernel_size, int) or isinstance(kernel_size, bool)
            or kernel_size <= 0 or kernel_size % 2 == 0):
        raise ValueError("kernel_size must be a positive odd integer")
    h = len(image)
    w = len(image[0])
    c = len(image[0][0])
    r = kernel_size // 2
    area = kernel_size * kernel_size
    out = []
    for i in range(h):
        row = []
        for j in range(w):
            sums = [0.0] * c
            for di in range(-r, r + 1):
                src = image[_reflect(i + di, h)]
                for dj in range(-r, r + 1):
                    px = src[_reflect(j + dj, w)]
                    for ch in range(c):
                        sums[ch] += px[ch]
            row.append([s / area for s in sums])
        out.append(row)
    return out

