        if freq == 'month-end':
            return date(y, m, calendar.monthrange(y, m)[1])
        if freq == 'quarter-end':
            if m % 3:
                return None
            return date(y, m, calendar.monthrange(y, m)[1])
        first = date(y, m, 1)
        offset = (wd - first.weekday()) % 7
        return first + timedelta(days=offset + 7 * (n - 1))

    y, m = start.year, start.month
    dates = []
    while len(dates) < len(sales):
        d = candidate(y, m)
        if d is not None and d >= start:
            dates.append(d)
        m += 1
        if m > 12:
            m = 1
            y += 1
    return [(d.isoformat(), s) for d, s in zip(dates, sales)]

