            pos += 1
        if start == pos:
            raise ValueError('invalid image')
        tokens.append(data[start:pos])
    magic = tokens[0]
    if magic not in (b'P2', b'P5'):
        raise ValueError('invalid image')
    try:
        width, height, maxval = (int(t) for t in tokens[1:])
    except ValueError:
        raise ValueError('invalid image')
    if width <= 0 or height <= 0 or not 0 < maxval <= 255:
        raise ValueError('invalid image')
    count = width * height
    if magic == b'P5':
        pos += 1
        pixels = list(data[pos:pos + count])
    else:
        try:
            pixels = [int(v) for v in data[pos:].split()[:count]]
        except ValueError:
            raise ValueError('invalid image')
    if len(pixels) < count:
        raise ValueError('invalid image')
    return dict(Counter(pixels))

