def classical_seasonal_decomposition(values, period, model='additive'):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    n = len(values)
    if n < 2 * period:
        raise ValueError('series must contain at least two full periods')
    x = [float(v) for v in values]
    additive = model == 'additive'
    if not additive and any(v <= 0 for v in x):
        raise ValueError('multiplicative model requires positive values')
    if period % 2:
        weights = [1.0 / period] * period
    else:
        weights = [0.5 / period] + [1.0 / period] * (period - 1) + [0.5 / period]
    half = len(weights) // 2
    trend = [None] * n
    for i in range(half, n - half):
        trend[i] = sum(w * x[i - half + k] for k, w in enumerate(weights))
    detrended = []
    for v, t in zip(x, trend):
        if t is None:
            detrended.append(None)
        else:
            detrended.append(v - t if additive else v / t)
    averages = []
    for j in range(period):
        vals = [d for d in detrended[j::period] if d is not None]
        averages.append(sum(vals) / len(vals))
    mean = sum(averages) / period
    if additive:
        averages = [a - mean for a in averages]
    else:
        averages = [a / mean for a in averages]
    seasonal = [averages[i % period] for i in range(n)]
    resid = []
    for v, t, s in zip(x, trend, seasonal):
        if t is None:
            resid.append(None)
        else:
            resid.append(v - t - s if additive else v / t / s)
    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}

